using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasIndex(p => p.Sku);

            // BREAKING CHANGE 1 — Discriminator property renamed.
            // EF9 default changed from "Discriminator" to "$type".
            // Existing 500K documents store "Discriminator"; raw SQL queries
            // (SELECT … WHERE c.Discriminator = 'Product') depend on this name.
            // Preserve the EF8 property name and value so existing docs are readable.
            b.HasDiscriminator<string>("Discriminator")
             .HasValue<Product>("Product");

            // BREAKING CHANGE 2 — Document id format changed.
            // EF8 synthesized id as "Product|{Key}" (e.g. "Product|123").
            // EF9 uses just the key value (e.g. "123").
            // Existing documents already have the old format, so we add an
            // explicit id property and generate values in the legacy format.
            b.Property(p => p.CosmosId)
             .ToJsonProperty("id")
             .HasValueGenerator<LegacyCosmosIdGenerator>();
        });
    }
}

class Product
{
    // Explicit Cosmos document id — preserves EF8 "Product|{Key}" format.
    public string CosmosId { get; set; } = null!;
    public int Id { get; set; }
    public string Sku { get; set; } = null!;
}

/// <summary>
/// Generates id values in the legacy EF8 format: "Product|{Id}".
/// </summary>
class LegacyCosmosIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;

    public override string Next(EntityEntry entry)
    {
        var key = entry.Property("Id").CurrentValue;
        return $"Product|{key}";
    }
}

