class CosmosQuery
{
    // BREAKING CHANGE 3 — Synchronous LINQ APIs removed.
    // EF9 Cosmos provider no longer supports sync calls (ToList, First, etc.).
    // All queries must use async counterparts (ToListAsync, FirstAsync, …).
    async Task FindProducts(ProductContext ctx)
    {
        // Raw Cosmos SQL — safe because we preserved "Discriminator" as the
        // discriminator property name (see ProductContext). No changes needed.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        var products = await ctx.Products
            .Where(p => p.Sku == "ABC")
            .ToListAsync();
    }
}

